async def act(page):
    # Plan:
    # 1. Navigate (relative goto) to the product reviews listing page in Magento Admin.
    # 2. Wait for network idle and a short timeout to allow rendering.
    # 3. Use Accessibility-tree-centric selectors (page.get_by_role) to collect all table rows.
