    # 1) Go to the reviews listing (relative URL for Magento 1.x reviews page)
    await page.goto("/index.php/admin/review_product/index/")
    await page.wait_for_load_state("networkidle")
    # small pause for any client-side rendering
    await page.wait_for_timeout(1000)

    # 2) Get all rows via accessibility role
    rows = page.get_by_role("row")
    total = await rows.count()

    seen = set()
    for i in range(total):
        row = rows.nth(i)
        try:
            text = (await row.inner_text()).strip()
        except Exception:
            # If inner_text fails for any row, skip it
            continue
        if not text:
            continue
        if "not useful" in text.lower():
            # normalize whitespace for deduplication
            norm = " ".join(text.split())
            seen.add(norm)

    # Print the number only (as required)
    print(len(seen))

